export type TransactionResponse = {
    account_id: string;
    account_name: string;
    /**
     * Decimal number encoded as a string (for example "1234.5600"); never a JSON number.
     */
    amount: string;
    category_color?: string | null;
    /**
     * The category's emoji (native clients' icon set).
     */
    category_emoji?: string | null;
    /**
     * The category's icon, a slug from the category icon set.
     */
    category_icon?: string | null;
    category_id?: string | null;
    /**
     * The category is a transfer category (“Transfers” and its children, or a custom one of type transfer), so the row counts as neither income nor spending, linked or not. Absent when false.
     */
    category_is_transfer?: boolean | null;
    /**
     * The category's display name in the request language: built-in categories that keep their seed name are translated ("Groceries" in English), custom and renamed ones are as stored.
     */
    category_name?: string | null;
    /**
     * How the background categorizer chose the row's category, when it did. Its needs_review is deprecated and always false.
     */
    category_review?: CategoryReview | null;
    /**
     * `counterpart_account_id` and `counterpart_account_name` are the account of the other leg of a transfer ("Wise → PrivatBank"); omitted otherwise.
     */
    counterpart_account_id?: string | null;
    counterpart_account_name?: string | null;
    /**
     * `counterpart_hidden` marks a transfer leg whose other side is on an account the caller can't see: clients show "Other account", and linked_transfer_id, counterpart_account_* and fee_transaction_id (when the fee is on that account) are omitted. direction stays transfer_in/transfer_out. Also true on a leg of a cross-space transfer: its other leg lives in another space (counterpart_space).
     */
    counterpart_hidden?: boolean | null;
    /**
     * `counterpart_space` names the other leg's space of a cross-space transfer: its name, or "Other space" (in the request language) when the caller is not a member of it or can't see its account (counterpart_space_hidden). counterpart_space_id, counterpart_account_* and counterpart_transaction_id are set only when the caller can see it.
     */
    counterpart_space?: string | null;
    counterpart_space_hidden?: boolean | null;
    counterpart_space_id?: string | null;
    /**
     * The other leg of a cross-space transfer, in counterpart_space_id: switch to that space (X-Space-ID) to open it. Set only when the caller is a member there and can see its account.
     */
    counterpart_transaction_id?: string | null;
    /**
     * The business counterparty the row is linked to; omitted when it has none.
     */
    counterparty_id?: string | null;
    /**
     * `counts_as_income` marks the personal leg of a cross-space transfer between a business and its owner's personal space: still a transfer, with the business's subcategory under “Income”, and counted in this space's income: an incoming leg adds its amount, an outgoing one (a top-up of the business) subtracts it; never in spending.
     */
    counts_as_income?: boolean | null;
    created_at: string;
    /**
     * The user id of the space member who added the row: a manual entry, transfer, split part, statement import, Suricate action or recurring posting. Omitted for bank, wallet and exchange imports and for rows whose author was never recorded.
     */
    created_by?: string | null;
    /**
     * The author's first name (else the local part of their email), also for members who have left the space; omitted with created_by.
     */
    created_by_name?: string | null;
    /**
     * `cross_space_transfer_id` marks a leg of a cross-space transfer (money moved between two linked spaces of the same owner, e.g. a personal card and a sole proprietor's account): both legs carry it.
     */
    cross_space_transfer_id?: string | null;
    description: string;
    /**
     * The sign of the always-positive amount on this account: income/transfer_in add to the balance, expense/transfer_out subtract.
     */
    direction: TransactionsTransactionDirection;
    /**
     * False for an operation on an account shared with the caller that their grant doesn't let them change: a balance or view grant, the account_sharing_write flag off for them, or, under edit_scope own, a row someone else added; and a read_only row. True for every other row; the space role and the row's own locks (a bank row, a split part) still apply.
     */
    editable?: boolean | null;
    /**
     * Decimal number encoded as a string (for example "1234.5600"); never a JSON number.
     */
    exchange_rate?: string | null;
    externalData: TransactionExternalDataResponse;
    /**
     * `fee_for_transfer_id` marks a transfer fee: the id of the transfer's outgoing leg (the transfer's id). Omitted for other transactions.
     */
    fee_for_transfer_id?: string | null;
    /**
     * The fee expense booked with this transfer (on the source account), on both legs; omitted when the transfer has no fee.
     */
    fee_transaction_id?: string | null;
    financials: TransactionFinancialsResponse;
    /**
     * How amount was found from the original: reference (our rate), card (with the account's own rate, learned from the bank's figures) or bank (the bank's figure); absent without an original or before it was recorded.
     */
    fx_basis?: 'reference' | 'card' | 'bank' | null;
    /**
     * `fx_correction_bps` is, for a row booked at the card's rate (fx_basis card), the account's correction it was booked with, in basis points from our rate (460 = +4.6%): the transaction's card-rate hint. Absent otherwise, and once a typed charge or our rate replaced it.
     */
    fx_correction_bps?: number | null;
    id: string;
    isDeleted: boolean;
    is_split: boolean;
    /**
     * "portfolio_transfer" for a transfer between two of the space's portfolio accounts (include_portfolio_transfers): its other fields are a list row's, `portfolio_transfer` carries the transfer, and it is read-only. Absent on a transaction.
     */
    kind?: 'portfolio_transfer' | null;
    /**
     * The wallet or exchange activity it was recorded from: network, hash with its explorer link, what moved and the fee. Omitted when it wasn't recorded from one the caller can see.
     */
    linked_activity?: LinkedActivityResponse | null;
    linked_transfer_id?: string | null;
    merchant?: string | null;
    merchant_brand?: BrandResponse | null;
    metadata: TransactionMetadataResponse;
    /**
     * `not_income` marks money coming in that is the person's own: left out of income, budgets and recaps, still in the account's balance. Omitted when false.
     */
    not_income?: boolean | null;
    note?: string | null;
    /**
     * Decimal number encoded as a string (for example "1234.5600"); never a JSON number.
     */
    original_amount?: string | null;
    original_currency?: string | null;
    parent_id?: string | null;
    place?: TransactionPlace | null;
    /**
     * `place_id`, `place_source` and Place are where the row happened: the place in the requester's language, as they may see it (another member's pin is its city); is_approximate for a place derived from a bank or CSV row. Omitted when none.
     */
    place_id?: string | null;
    place_source?: 'device' | 'picked' | 'receipt' | 'merchant' | 'ai' | null;
    /**
     * The transfer of a row of kind "portfolio_transfer".
     */
    portfolio_transfer?: TransferResponse | null;
    /**
     * The business project of the row or split part; omitted when it has none.
     */
    project_id?: string | null;
    /**
     * The badge of its reactions and comments in a shared space; omitted when it has neither.
     */
    reactions?: ReactionsSummary | null;
    /**
     * `read_only` marks a row nothing may edit, delete or record (a portfolio transfer).
     */
    read_only?: boolean | null;
    /**
     * The recurring rule whose occurrence this row settles; omitted when none.
     */
    recurring_rule_id?: string | null;
    relationships: TransactionRelationshipsResponse;
    /**
     * `service_period_from` and `service_period_to` are the period a business operation pays for: the accrual P&L spreads it over these days.
     */
    service_period_from?: string | null;
    service_period_to?: string | null;
    space_id: string;
    /**
     * The user id of the participant whose own spending this row of a pooled shared account is: the share takes it whole from their part. Omitted while the share splits it.
     */
    spent_by?: string | null;
    /**
     * That participant's first name (as created_by_name); omitted with spent_by.
     */
    spent_by_name?: string | null;
    splits?: Array<TransactionResponse> | null;
    status: TransactionStatus;
    /**
     * The transaction's tags, by name; omitted when it has none.
     */
    tags?: Array<TransactionTag> | null;
    timestamps: TransactionTimestampsResponse;
    transaction_date: string;
    /**
     * The tax treatment of a business-space row (its class, who decided it, how sure and whether a person reviewed it); omitted in personal spaces and for rows without one (a split parent, a cancelled row, a row the worker has not reached yet).
     */
    treatment?: TransactionTreatment | null;
    /**
     * The stored type: transfer legs keep income/expense here (see direction, or metadata.transactionType, for the transfer view).
     */
    type: TransactionsTransactionType;
    /**
     * UAHAmount is the legal hryvnia value of a business-space row: the amount at the official NBU rate of the account currency on the legal date (uah_rate_date, the Kyiv calendar day of transaction_date), rounded to kopecks and frozen; the amount itself on a UAH account. Omitted in personal spaces and while uah_status is pending_rate.
     */
    uah_amount?: string | null;
    /**
     * UAHRate is hryvnias per one unit of the account currency used for uah_amount (1 on a UAH account).
     */
    uah_rate?: string | null;
    /**
     * UAHRateDate is the legal date of the valuation.
     */
    uah_rate_date?: string | null;
    /**
     * UAHStatus is the valuation state of a business-space row: ok, pending_rate (no value yet: just written, or the NBU has not published the rate of that day; reports leave the row out and count it in pending_valuation) or locked (a declared or locked period, never recomputed). Omitted in personal spaces.
     */
    uah_status?: 'ok' | 'pending_rate' | 'locked' | null;
    updated_at: string;
    /**
     * The row version (also the ETag): send it back as If-Match on PATCH and DELETE to detect concurrent edits (412).
     */
    version?: number | null;
};

